// ---------- assembly (closed / seated: lugs down the entries, lid flush) ----------
// Twist +90° about Z from here to lock (motion twist_lock).
module assembly() {
    instance("jar","jar") jar();
    instance("lid","lid")
        translate([0,0,asmTop]) rotate([180,0,0]) lid();
}

